import json
from datetime import datetime

def process_data(data):
    # Filter items with a positive 'value' and build processed records.
    # Each record includes the original 'id', a 'processed' flag, and an ISO timestamp.
    # Returns a list of processed dicts; items with missing or non-positive 'value' are skipped.
    result = []
    for item in data:
        if item.get('value', 0) > 0:
            result.append({
                'id': item.get('id'),
                'processed': True,
                'timestamp': datetime.now().isoformat()
            })
    return result

def calculate_avg(nums):
    # Compute the arithmetic mean of a list of numbers.
    # Returns 0 when the list is empty to avoid a ZeroDivisionError.
    total = 0
    count = len(nums)
    for n in nums:
        total += n
    return total / count if count > 0 else 0

def filter_users(users, min_age=18):
    # Return only users whose 'age' meets or exceeds min_age (defaults to 18).
    # Users missing an 'age' key are treated as age 0 and therefore excluded.
    filtered = []
    for user in users:
        if user.get('age', 0) >= min_age:
            filtered.append(user)
    return filtered

def save_to_file(data, filename):
    # Serialize data as JSON and write it to filename.
    # Returns True on success; raises an OSError/IOError if the file cannot be opened or written.
    with open(filename, 'w') as f:
        json.dump(data, f)
    return True

class DataStore:
    def __init__(self):
        # Initialize the store with an empty internal dictionary.
        self._data = {}

    def add(self, key, value):
        # Insert or overwrite the value associated with key.
        # No return value.
        self._data[key] = value

    def get(self, key):
        # Retrieve the value for key, or None if the key is absent.
        return self._data.get(key)

    def remove(self, key):
        # Delete the entry for key if it exists; silently no-op if the key is missing.
        if key in self._data:
            del self._data[key]

def format_output(items):
    # Format items into a numbered, newline-separated string (e.g., "1. foo\n2. bar").
    # Assumes items are stringifiable; returns an empty string for an empty input list.
    output = []
    for i, item in enumerate(items):
        output.append(f"{i+1}. {item}")
    return "\n".join(output)

